const programs={strength:{name:'Everyday strength',label:'STRENGTH & CONFIDENCE',title:'A little stronger.\nA lot more capable.',description:'Build a foundation of strength with a progressive plan that meets you where you are. For carrying the groceries, taking the stairs, and feeling more at home in your body.',features:['Personalized strength programming','Technique-focused sessions','Progress reviews and adjustments'],image:'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=85',alt:'Athlete preparing for a strength training session',caption:'01 / STRENGTH, WITH INTENTION'},movement:{name:'Move with ease',label:'MOBILITY & EVERYDAY MOVEMENT',title:'Move a little better.\nEnjoy a little more.',description:'Make room for comfortable, confident movement. A thoughtful blend of mobility, bodyweight training, and coordination shaped around your experience and everyday activities.',features:['Movement-focused programming','Mobility and coordination practice','A routine adapted to your starting point'],image:'https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=1200&q=85',alt:'Athlete stretching in a bright studio',caption:'02 / ROOM TO MOVE'},online:{name:'Coaching, anywhere',label:'PERSONAL GUIDANCE, WHEREVER YOU ARE',title:'Your space. Your pace.\nStill personal.',description:'Bring structure to training wherever life takes you. A plan built around your space, your equipment, and your routine, with coaching details agreed before you get started.',features:['Programming for your available equipment','A schedule shaped around your life','Check-ins and reviews agreed with your trainer'],image:'https://images.unsplash.com/photo-1599058917212-d750089bc07e?auto=format&fit=crop&w=1200&q=85',alt:'A functional training space',caption:'03 / YOUR TRAINING, YOUR SPACE'}};
let active='strength';const tabs=[...document.querySelectorAll('[role=tab]')];
function activate(key,focus=false){active=key;const p=programs[key];tabs.forEach(tab=>{const selected=tab.dataset.program===key;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;if(selected&&focus)tab.focus()});document.querySelector('#program-content').setAttribute('aria-labelledby','tab-'+key);document.querySelector('#program-label').textContent=p.label;const title=document.querySelector('#program-title');title.replaceChildren();p.title.split('\n').forEach((line,i)=>{if(i)title.append(document.createElement('br'));title.append(document.createTextNode(line))});document.querySelector('#program-description').textContent=p.description;document.querySelector('#program-features').replaceChildren(...p.features.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));const image=document.querySelector('#program-photo');image.src=p.image;image.alt=p.alt;document.querySelector('#photo-caption').textContent=p.caption}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(tab.dataset.program));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(i+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();activate(tabs[next].dataset.program,true)}})});
const toggle=document.querySelector('.menu');const nav=document.querySelector('#main-nav');function closeMenu(){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu')});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();toggle.focus()}});
document.querySelector('#choose-program').addEventListener('click',()=>{document.querySelector('#interest').value=programs[active].name;if(active==='online')document.querySelector('input[name=format][value=Online]').checked=true;document.querySelector('#start').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});document.querySelector('#visitor-name').focus({preventScroll:true})});
const dialog=document.querySelector('#intro-dialog'),output=document.querySelector('#intro-output'),status=document.querySelector('#copy-status');document.querySelector('#intro-form').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.currentTarget);const name=String(form.get('name')).trim();if(!name){const input=document.querySelector('#visitor-name');input.setCustomValidity('Please enter your first name.');input.reportValidity();return}output.value=`Hi, I’m ${name}.\n\nI’d love to learn more about FORM coaching.\nMy starting point: ${form.get('interest')}.\nPreferred format: ${form.get('format')}.\n\nCould we talk about the right approach, availability, and pricing?`;status.textContent='';dialog.showModal()});document.querySelector('#visitor-name').addEventListener('input',e=>e.target.setCustomValidity(''));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#copy-intro').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(output.value);status.textContent='Copied. Your introduction is ready to share.'}catch{output.focus();output.select();status.textContent='Select the text and copy it with Ctrl+C or your device’s copy menu.'}});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion:reduce)').matches){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}document.querySelector('#year').textContent=new Date().getFullYear();
